function isUidBlocked(game: GameRuntime, uid: string): boolean {
    if (game.isUidInUltimateSlot?.(uid)) return true;
    if (game.isCreatureRocketLocked) {
        const all = [...(game.storage ?? []), ...(game.pension ?? []), ...(game.playerTeam ?? [])];
        const c = all.find((x) => String(x.uid) === uid);
        if (c && game.isCreatureRocketLocked(c)) return true;
    }
    return false;
}

function buildCandidates(
    game: GameRuntime,
    assignedByUid: Map<string, PokePelagoIslandId>,
    ui: PokePelagoUiSnapshot,
): PokePelagoAssignCandidateSnapshot[] {
    const out: PokePelagoAssignCandidateSnapshot[] = [];
    for (let i = 0; i < (game.storage ?? []).length; i++) {
        const creature = game.storage![i];
        if (!creature?.uid) continue;
        const uid = String(creature.uid);
        const blocked = isUidBlocked(game, uid);
        const assignedIslandId = assignedByUid.get(uid) ?? null;
        const atMaxLevel = isCreatureAtMaxLevel(creature);
        let disabledReason: string | null = null;
        if (blocked) disabledReason = ui.blocked;
        else if (assignedIslandId) disabledReason = ui.alreadyAssigned;
        out.push({
            uid,
            storageIndex: i,
            name: creatureDisplayName(game, creature),
            level: Math.max(1, Number(creature.level) || 1),
            spriteUrl: getPokemonSpriteUrl(String(creature.name || ''), !!creature.isShiny, false),
            atMaxLevel,
            disabled: blocked,
            disabledReason,
            assignedIslandId,
        });
    }
    out.sort((a, b) => b.level - a.level || a.name.localeCompare(b.name));
    return out;
}

function fractionalFill(value: number): number {
    if (!(value > 0)) return 0;
    if (Math.floor(value) >= 1) return 1;
    return Math.min(1, Math.max(0, value % 1));
}

function fractionalDisplay(value: number, digits = 2): string {
    if (Math.floor(value) >= 1) return (1).toFixed(digits);
    if (!(value > 0)) return (0).toFixed(digits);
    return value.toFixed(digits);
}

function formatRateLabel(
    game: GameRuntime,
    ui: PokePelagoUiSnapshot,
    islandId: PokePelagoIslandId,
    rates: ReturnType<typeof getIslandHourlyRates>,
    hasAssignee: boolean,
): string | null {
    if (!hasAssignee) return ui.rateIdle;
    if (islandId === 'abeens') {
        return pelagoT(game, 'pokePelago.rateAbeens', ui.rateAbeens, ui.rateAbeens, {
            shards: rates.shardsPerHour.toFixed(2),
            beans: rates.beansPerHour.toFixed(2),
            stones: rates.prestigeStonesPerHour.toFixed(3),
        });
    }
    if (islandId === 'aphun') {
        const hoursPerItem = rates.itemRollPerHour > 0 ? (1 / rates.itemRollPerHour) : 0;
        return pelagoT(game, 'pokePelago.rateItems', ui.rateItems, ui.rateItems, {
            h: hoursPerItem > 0 ? hoursPerItem.toFixed(1) : '—',
        });
    }
    if (islandId === 'evelup') {
        return pelagoT(game, 'pokePelago.rateXp', ui.rateXp, ui.rateXp, {
            n: Math.round(rates.xpPerHour),
        });
    }
    return null;
}

function formatProgressLabel(
    game: GameRuntime,
    ui: PokePelagoUiSnapshot,
    islandId: PokePelagoIslandId,
    slot: { pendingShards: number; pendingBeans?: number; pendingXp: number; pendingItems: { itemKey: string; qty: number }[] },
    hasAssignee: boolean,
): string | null {
    if (!hasAssignee) return null;
    // Abeens uses progressRows (label + gauge). Evelup: text only, no gauge.
    if (islandId === 'evelup') {
        if (Math.floor(slot.pendingXp) >= 1) return null;
        return pelagoT(game, 'pokePelago.progressXp', ui.progressXp, ui.progressXp, {
            current: fractionalDisplay(slot.pendingXp, 1),
        });
    }
    return null;
}

function buildProgressRows(
    game: GameRuntime,
    ui: PokePelagoUiSnapshot,
    islandId: PokePelagoIslandId,
    slot: {
        pendingShards: number;
        pendingBeans?: number;
        pendingPrestigeStones?: number;
        pendingXp: number;
    },
    hasAssignee: boolean,
): { id: string; label: string; fill: number }[] {
    if (!hasAssignee) return [];
    if (islandId === 'abeens') {
        const shards = slot.pendingShards;
        const beans = slot.pendingBeans ?? 0;
        const stones = slot.pendingPrestigeStones ?? 0;
        return [
            {
                id: 'shards',
                label: pelagoT(game, 'pokePelago.progressShards', ui.progressShards, ui.progressShards, {
                    current: fractionalDisplay(shards),
                }),
                fill: fractionalFill(shards),
            },
            {
                id: 'beans',
                label: pelagoT(game, 'pokePelago.progressBeans', ui.progressBeans, ui.progressBeans, {
                    current: fractionalDisplay(beans),
                }),
                fill: fractionalFill(beans),
            },
            {
                id: 'prestige',
                label: pelagoT(game, 'pokePelago.progressPrestige', ui.progressPrestige, ui.progressPrestige, {
                    current: fractionalDisplay(stones),
                }),
                fill: fractionalFill(stones),
            },
        ];
    }
    return [];
}

function formatEtaLabel(
    game: GameRuntime,
    ui: PokePelagoUiSnapshot,
    islandId: PokePelagoIslandId,
    slot: { pendingShards: number; pendingXp: number; pendingItems: { itemKey: string; qty: number }[] },
    rates: ReturnType<typeof getIslandHourlyRates>,
    hasAssignee: boolean,
): string | null {
    if (!hasAssignee) return null;
    const etaMs = estimateIslandEtaMs(islandId, slot as never, rates);
    if (etaMs == null) return null;
    if (etaMs <= 0) return ui.etaReady;
    const time = formatFarmDuration(etaMs, langOf(game));
    return pelagoT(game, 'pokePelago.etaIn', ui.etaIn, ui.etaIn, { time });
}

function formatPendingLabel(
    game: GameRuntime,
    ui: PokePelagoUiSnapshot,
    islandId: PokePelagoIslandId,
    slot: {
        pendingShards: number;
        pendingXp: number;
        pendingBeans?: number;
        pendingPrestigeStones?: number;
        pendingItems: { itemKey: string; qty: number }[];
    },
    hasAssignee: boolean,
): { label: string; items: { itemKey: string; name: string; qty: number; iconUrl: string | null }[] } {
    const parts: string[] = [];
    const shards = Math.floor(slot.pendingShards);
    const xp = Math.floor(slot.pendingXp);
    const beans = Math.floor(slot.pendingBeans ?? 0);
    const prestigeStones = Math.floor(slot.pendingPrestigeStones ?? 0);
    if (shards >= 1) {
        parts.push(pelagoT(game, 'pokePelago.pendingShards', ui.pendingShards, ui.pendingShards, { n: shards }));
    }
    if (beans >= 1) {
        parts.push(pelagoT(game, 'pokePelago.pendingBeans', ui.pendingBeans, ui.pendingBeans, { n: beans }));
    }
    if (prestigeStones >= 1) {
        parts.push(pelagoT(game, 'pokePelago.pendingPrestige', ui.pendingPrestige, ui.pendingPrestige, {
            n: prestigeStones,
        }));
    }
    if (xp >= 1) {
        parts.push(pelagoT(game, 'pokePelago.pendingXp', ui.pendingXp, ui.pendingXp, { n: xp }));
    }
    const items = slot.pendingItems.map((it) => {
        let iconUrl: string | null = null;
        try {
            iconUrl = getItemIconPath(it.itemKey) || null;
        } catch {
            iconUrl = null;
        }
        return {
            itemKey: it.itemKey,
            name: itemLabel(game, it.itemKey),
            qty: it.qty,
            iconUrl,
        };
    });
    // Items rendered separately in the modal list — keep claimable summary short.
    if (parts.length || items.length) {
        return { label: parts.join(' · '), items };
    }
    // Fractional progress: don't show "nothing" when accumulating
    if (hasAssignee && islandId === 'abeens'
        && ((slot.pendingShards > 0 && slot.pendingShards < 1)
            || ((slot.pendingBeans ?? 0) > 0 && (slot.pendingBeans ?? 0) < 1)
            || ((slot.pendingPrestigeStones ?? 0) > 0 && (slot.pendingPrestigeStones ?? 0) < 1))) {
        return { label: '', items };
    }
    if (hasAssignee && islandId === 'evelup' && slot.pendingXp > 0 && slot.pendingXp < 1) {
        return { label: '', items };
    }
    return { label: ui.nothingPending, items };
}

function buildAphunPoolHint(game: GameRuntime, ui: PokePelagoUiSnapshot): string {
    const names = POKE_PELAGO_APHUN_POOL.map((e) => itemLabel(game, e.itemKey));
    const short = names.slice(0, 4).join(', ') + (names.length > 4 ? '…' : '');
    return pelagoT(game, 'pokePelago.aphunPoolHint', ui.aphunPoolHint, ui.aphunPoolHint, { items: short });
}

function buildCreatureUidMap(game: GameRuntime): Map<string, CreatureData> {
    const creatureByUid = new Map<string, CreatureData>();
    for (const c of game.storage ?? []) {
        if (c?.uid) creatureByUid.set(String(c.uid), c);
    }
    for (const c of game.pension ?? []) {
        if (c?.uid) creatureByUid.set(String(c.uid), c);
    }
    for (const c of game.playerTeam ?? []) {
        if (c?.uid) creatureByUid.set(String(c.uid), c);
    }
    if (game.ultimateSlot?.uid) creatureByUid.set(String(game.ultimateSlot.uid), game.ultimateSlot);
    return creatureByUid;
}

export function buildPokePelagoSnapshot(game: GameRuntime): PokePelagoSnapshot {
    const ui = buildUi(game);
    const unlocked = !!(game.pokePelagoState?.unlocked || game.unlockedFeatures?.pokePelago);
    const emptyLevel = {
        level: 1,
        levelBonusPercent: 0,
        xpTowardNextLevel: 0,
        xpPerLevel: POKE_PELAGO.xpPerLevel,
        beans: 0,
        isMaxLevel: false,
        levelLabel: pelagoT(game, 'pokePelago.levelLabel', ui.levelLabel, ui.levelLabel, { level: 1 }),
        levelBonusLabel: pelagoT(game, 'pokePelago.levelBonus', ui.levelBonus, ui.levelBonus, { pct: 0 }),
        levelProgressLabel: pelagoT(
            game,
            'pokePelago.levelProgress',
            ui.levelProgress,
            ui.levelProgress,
            { current: 0, need: POKE_PELAGO.xpPerLevel },
        ),
        beansLabel: '',
        beansHint: ui.beansHint,
        evelupBanner: null as string | null,
    };
    if (!game.pokePelagoState) {
        return {
            unlocked: false,
            claimableCount: 0,
            claimableBadgeTitle: null,
            ...emptyLevel,
            islands: [],
            candidates: [],
            ui,
        };
    }
    const state = normalizePokePelagoState(game.pokePelagoState);
    game.pokePelagoState = state;
    if (!state.unlocked && !unlocked) {
        return {
            unlocked: false,
            claimableCount: 0,
            claimableBadgeTitle: null,
            ...emptyLevel,
            islands: [],
            candidates: [],
            ui,
        };
    }

    const crystalCount = getZRingState(game).unlockedCrystalIds.length;
    const creatureByUid = buildCreatureUidMap(game);
    if (clearGhostPelagoAssignees(state, creatureByUid)) {
        game.saveGame?.();
    }

    const assignedByUid = new Map<string, PokePelagoIslandId>();
    for (const id of POKE_PELAGO_ISLAND_IDS) {
        const uid = state.islands[id].assignedUid;
        if (uid) assignedByUid.set(uid, id);
    }

    const aphunPool = buildAphunPoolHint(game, ui);
    const bonusPct = getPelagoLevelBonusPercent(state.level);
    const isMaxLevel = Number.isFinite(POKE_PELAGO.maxLevel) && state.level >= POKE_PELAGO.maxLevel;
    const levelLabel = pelagoT(game, 'pokePelago.levelLabel', ui.levelLabel, ui.levelLabel, {
        level: state.level,
    });
    const levelBonusLabel = pelagoT(game, 'pokePelago.levelBonus', ui.levelBonus, ui.levelBonus, {
        pct: bonusPct,
    });
    const levelProgressLabel = isMaxLevel
        ? ui.levelMax
        : pelagoT(game, 'pokePelago.levelProgress', ui.levelProgress, ui.levelProgress, {
            current: Math.floor(state.xpTowardNextLevel),
            need: POKE_PELAGO.xpPerLevel,
        });
    const beansLabel = '';

    const evelupBanner = pendingEvelupBanner;
    pendingEvelupBanner = null;

    const islands: PokePelagoIslandSnapshot[] = POKE_PELAGO_ISLAND_IDS.map((id) => {
        const slot = state.islands[id];
        const open = isIslandUnlocked(state, id, crystalCount);
        const creature = slot.assignedUid ? creatureByUid.get(slot.assignedUid) ?? null : null;
        const rates = getIslandHourlyRates(state, id, creature, crystalCount);
        const pending = formatPendingLabel(game, ui, id, slot, !!creature);
        const nameKey = id === 'abeens' ? ui.nameAbeens : id === 'aphun' ? ui.nameAphun : ui.nameEvelup;
        const role = id === 'abeens' ? ui.roleAbeens : id === 'aphun' ? ui.roleAphun : ui.roleEvelup;
        let unlockHint: string | null = null;
        if (!open && id === 'evelup') {
            unlockHint = pelagoT(
                game,
                'pokePelago.evelupUnlockHint',
                ui.evelupUnlockHint,
                ui.evelupUnlockHint,
                { need: POKE_PELAGO.evelupUnlockMinCrystals, have: crystalCount },
            );
        } else if (!open) {
            unlockHint = ui.lockedGeneric;
        }

        let offlineHint: string | null = null;
        if (open && id === 'abeens') {
            const rateForHint = creature
                ? rates.shardsPerHour
                : POKE_PELAGO.abeensBaseShardsPerHour;
            const offlineN = estimateAbeensOfflineShards(rateForHint);
            offlineHint = pelagoT(
                game,
                'pokePelago.offlineShardsHint',
                ui.offlineShardsHint,
                ui.offlineShardsHint,
                { n: offlineN.toFixed(1) },
            );
        }

        let progressFill: number | null = null;
        let beansProgressFill: number | null = null;
        let prestigeProgressFill: number | null = null;
        if (open && creature) {
            if (id === 'abeens') {
                progressFill = fractionalFill(slot.pendingShards);
                beansProgressFill = fractionalFill(slot.pendingBeans ?? 0);
                prestigeProgressFill = fractionalFill(slot.pendingPrestigeStones ?? 0);
            }
        }

        const assignedLevel = creature ? Math.max(1, Number(creature.level) || 1) : null;
        const assigneeBonusPct = assignedLevel != null ? getAssigneeLevelBonusPercent(assignedLevel) : 0;
        const alolaAffinity = creature && id === 'abeens'
            ? getAbeensAlolaAffinityMult(creature) > 1
            : false;
        let assigneeBonusLabel: string | null = null;
        if (creature && (id === 'abeens' || id === 'aphun' || id === 'evelup')) {
            if (id === 'abeens' && alolaAffinity) {
                const alolaPct = Math.round((POKE_PELAGO.abeensAlolaAffinityMult - 1) * 100);
                assigneeBonusLabel = pelagoT(
                    game,
                    'pokePelago.assigneeBonusAlola',
                    ui.assigneeBonusAlola,
                    ui.assigneeBonusAlola,
                    { pct: assigneeBonusPct, alola: alolaPct },
                );
            } else {
                assigneeBonusLabel = pelagoT(
                    game,
                    'pokePelago.assigneeBonus',
                    ui.assigneeBonus,
                    ui.assigneeBonus,
                    { pct: assigneeBonusPct },
                );
            }
        }

        const products = id === 'abeens'
            ? [ui.productAbeensShards, ui.productAbeensXp, ui.productAbeensPrestige]
            : id === 'aphun'
                ? [ui.productAphunItems]
                : [ui.productEvelupXp];

        return {
            id,
            name: nameKey,
            role,
            unlocked: open,
            unlockHint,
            claimable: open && islandHasClaimable(slot),
            assignedUid: slot.assignedUid,
            assignedName: creature ? creatureDisplayName(game, creature) : null,
            assignedLevel,
            assignedSpriteUrl: creature
                ? getPokemonSpriteUrl(String(creature.name || ''), !!creature.isShiny, false)
                : null,
            assigneeBonusLabel,
            products,
            rateLabel: open ? formatRateLabel(game, ui, id, rates, !!creature) : null,
            progressLabel: open ? formatProgressLabel(game, ui, id, slot, !!creature) : null,
            progressRows: open ? buildProgressRows(game, ui, id, slot, !!creature) : [],
            progressFill,
            beansProgressFill,
            prestigeProgressFill,
            etaLabel: open ? formatEtaLabel(game, ui, id, slot, rates, !!creature) : null,
            offlineHint: open ? offlineHint : null,
            poolHint: open && id === 'aphun' ? aphunPool : null,
            pityLabel: open && id === 'aphun'
                ? pelagoT(game, 'pokePelago.aphunPity', ui.aphunPity, ui.aphunPity, {
                    current: state.aphunRollsSinceRare,
                    need: POKE_PELAGO.aphunPityThreshold,
                })
                : null,
            pendingLabel: open ? pending.label : '',
            pendingShards: slot.pendingShards,
            pendingBeans: slot.pendingBeans ?? 0,
            pendingPrestigeStones: slot.pendingPrestigeStones ?? 0,
            pendingXp: slot.pendingXp,
            pendingItems: pending.items,
        };
    });

    const claimableCount = countClaimablePelagoIslands(state, crystalCount);
    return {
        unlocked: true,
        claimableCount,
        claimableBadgeTitle: claimableCount > 0
            ? pelagoT(game, 'pokePelago.badgeTitle', ui.badgeTitle, ui.badgeTitle, { n: claimableCount })
            : null,
        level: state.level,
        levelBonusPercent: bonusPct,
        xpTowardNextLevel: state.xpTowardNextLevel,
        xpPerLevel: POKE_PELAGO.xpPerLevel,
        beans: state.beans,
        isMaxLevel,
        levelLabel,
        levelBonusLabel,
        levelProgressLabel,
        beansLabel,
        beansHint: ui.beansHint,
        evelupBanner,
        islands,
        candidates: buildCandidates(game, assignedByUid, ui),
        ui,
    };
}

function tryAnnounceEvelupUnlock(game: GameRuntime, ui: PokePelagoUiSnapshot): void {
    const state = game.pokePelagoState;
    if (!state?.unlocked) return;
    const crystals = getZRingState(game).unlockedCrystalIds.length;
    if (!isIslandUnlocked(state, 'evelup', crystals)) return;
    if (!markEvelupUnlockSeen(state)) return;
    pendingEvelupBanner = ui.evelupUnlockedBanner;
    const lang = langOf(game);
    logMessage(lang === 'en'
        ? 'Isle Evelup unlocked! Claimed XP goes to the assigned Pokémon.'
        : 'Île Evelup débloquée ! L’XP récoltée va au Pokémon assigné.');
    game.saveGame?.();
}

export function pokePelagoSnapshotWouldChange(a: PokePelagoSnapshot, b: PokePelagoSnapshot): boolean {
    return JSON.stringify(a) !== JSON.stringify(b);
}

export function notifyPokePelagoChanged(game: GameRuntime, options?: { force?: boolean }): void {
    if (!game.pokePelagoState && !game.unlockedFeatures?.pokePelago) {
        const empty = buildPokePelagoSnapshot(game);
        if (!options?.force && lastSnapshot && !pokePelagoSnapshotWouldChange(lastSnapshot, empty)) return;
        lastSnapshot = empty;
        publish({ type: Evt.POKE_PELAGO_CHANGED, pokePelago: empty });
        return;
    }
    if (!game.pokePelagoState && game.unlockedFeatures?.pokePelago) {
        game.pokePelagoState = createDefaultPokePelagoState(Date.now());
        game.pokePelagoState.unlocked = true;
    }
    const ui = buildUi(game);
    tryAnnounceEvelupUnlock(game, ui);
    const snap = buildPokePelagoSnapshot(game);
    if (!options?.force && lastSnapshot && !pokePelagoSnapshotWouldChange(lastSnapshot, snap)) {
        return;
    }
    lastSnapshot = snap;
    publish({ type: Evt.POKE_PELAGO_CHANGED, pokePelago: snap });
}

/** Throttled publish while Pelago modal is open (pending / ETA live). */
export function maybePublishPokePelagoLiveRefresh(
    game: GameRuntime,
    now: number,
    shouldRefresh: boolean,
): void {
    if (!shouldRefresh) return;
    if (now - lastLivePublishAt < 1000) return;
    lastLivePublishAt = now;
    notifyPokePelagoChanged(game, { force: true });
}

/** @internal Vitest */
export function resetPokePelagoSnapshotDedupForTests(): void {
    lastSnapshot = null;
    lastLivePublishAt = 0;
    pendingEvelupBanner = null;
}

export function getLastPokePelagoLivePublishAtForTests(): number {
    return lastLivePublishAt;
}
